INSERT INTO `scholarship_announcements` VALUES
('1', '3', 'MyPtptn', 'Skim Pinjaman Pendidikan PTPTN diwujudkan bagi tujuan untuk memberi pinjaman pendidikan kepada pelajar yang mengikuti pengajian di Institusi Pendidikan Tinggi (IPT) tempatan. Pinjaman pendidikan ini akan membolehkan pelajar membiayai sepenuh atau sebahagian yuran pengajian dan juga kos sara hidup sepanjang tempoh pengajian. Kemudahan pinjaman pendidikan PTPTN adalah terbuka kepada pelajar yang menyambung pengajian di Institusi Pendidikan Tinggi Awam (IPTA) dan Institusi Pendidikan Tinggi Swasta (IPTS) tempatan sahaja.', 'scholarship', 'https://www.ptptn.gov.my/pinjaman-pendidikan/', NULL, NULL, NULL, NULL, '2026-04-24 14:47:41', '2026-07-10 21:49:23');
